// The project's layers. Undo of an add calls removeLayer(); redo calls addLayer() again with the
// same layer. on(fn) is called with ('add' | 'remove', layer) for each change.
export class Project {
  constructor() {
    this.layers = new Map();
    this.listeners = [];
  }

  addLayer(layer) {
    this.layers.set(layer.id, layer);
    this.emit('add', layer);
  }

  removeLayer(id) {
    const layer = this.layers.get(id);
    this.layers.delete(id);
    this.emit('remove', layer);
  }

  on(fn) {
    this.listeners.push(fn);
  }

  emit(type, layer) {
    for (const fn of this.listeners) fn(type, layer);
  }
}

