// Terrains: DEM layers used as terrain.
export class Terrains {
  constructor(project) {
    this.project = project;
    this.list = [];
    this.target = null;
  }

  use(layer, grid) {
    const entry = { layerId: layer.id, grid };
    this.list.push(entry);
    this.target = entry;
    return entry;
  }

  saveTarget(writer) {
    const layer = this.project.layers.get(this.target.layerId);
    return writer.write(layer.name, this.target.grid);
  }
}
